const input = $json.body ?? $json;
const contentId = String(input.contentId ?? '').trim();
const locationId = String(input.locationId ?? '').trim();
const userId = String(input.userId ?? '').trim();
const accountIds = Array.isArray(input.accountIds) ? input.accountIds.map(String).map(v => v.trim()).filter(Boolean) : [];
const rawDraft = String(input.draft ?? '').trim();
const summary = rawDraft
  .replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1')
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/__([^_]+)__/g, '$1')
  .replace(/(^|[\s(])\*([^*\n]+)\*(?=$|[\s).,!?])/g, '$1$2')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const rawScheduleDate = String(input.scheduleDate ?? '').trim();
let scheduleDate = '';
if (rawScheduleDate) {
  const timestamp = Date.parse(rawScheduleDate);
  if (!Number.isFinite(timestamp) || timestamp <= Date.now() + 60000) throw new Error('scheduleDate must be at least one minute in the future');
  scheduleDate = new Date(timestamp).toISOString();
}
const imageUrl = String(input.imageUrl ?? '').trim();
const requestedImageMimeType = String(input.imageMimeType ?? '').trim().toLowerCase();
const allowedImageTypes = ['image/jpeg', 'image/png', 'image/webp'];
const imageMimeType = allowedImageTypes.includes(requestedImageMimeType) ? requestedImageMimeType : 'image/jpeg';
const media = /^https:\/\/[^\s]+$/i.test(imageUrl) ? [{ url: imageUrl, type: imageMimeType, caption: '' }] : [];
if (!contentId) throw new Error('contentId is required');
if (!locationId) throw new Error('locationId is required');
if (!userId) throw new Error('userId is required');
if (!accountIds.length) throw new Error('At least one GHL account ID is required');
if (!summary) throw new Error('Approved draft is required');
return [{ json: { contentId, locationId, userId, accountIds, summary, media, imageReceived: Boolean(imageUrl), type: 'post', status: scheduleDate ? 'scheduled' : 'published', scheduleDate, approvedAt: new Date().toISOString() } }];

const request = $('Validate Publish Request').item.json;
const response = $json;
if (!response.success || Number(response.statusCode) < 200 || Number(response.statusCode) >= 300) throw new Error(response.message || 'GoHighLevel rejected the post');
const post = response.results?.post ?? {};
const status = post.status === 'scheduled' || request.status === 'scheduled' ? 'scheduled' : request.status === 'published' || post.status === 'published' ? 'published' : 'approved';
const externalId = post._id ?? post.id ?? response.traceId ?? request.contentId;
return [{ json: { contentId: request.contentId, status, externalId, mediaAttached: request.media.length > 0, scheduledAt: status === 'scheduled' ? request.scheduleDate : null, publishedAt: status === 'published' ? new Date().toISOString() : null, message: response.message || 'Content sent to GoHighLevel successfully.' } }];
